  /* ===================== Сцена: мир без разницы и флажок наблюдения ===================== */
  const SC = { ink: '#e8ecf4', ink2: '#b7c0d2', mut: '#8d95aa', box: '#141b2b', old: '#6fa2ea', neu: '#f0a247', nul: '#36b8a6', tail: '#f06ba5', crit: '#f2756a', yel: '#e3c04d', grey: '#a9b1c2' };
  const OLD = DATA.old.map(v => v * 10), NEWV = DATA.base.map(v => v * 10 + DATA.effect);
