  const D0 = DATA.d0, OBS = DATA.obs, CR = DATA.crit, CI = DATA.ci, K0 = D0.length;
  const MO = avg(OLD), MN = avg(NEWV);
  const HLO = -2500, HBW = 100, HNB = 50, XTOP = 14000;
  const histK = k => { const h = new Array(HNB).fill(0); for (let i = 0; i < k; i++) { const b = Math.floor((D0[i] - HLO) / HBW); if (b >= 0 && b < HNB) h[b]++; } return h; };
  const HALL = histK(K0), HMAX = Math.max(...HALL), AMAX = Math.max(...DATA.alt);
