      function txt(t, x, y, col, al, align, base, f) { g.save(); g.globalAlpha = al; g.font = f || `500 ${fs}px ${FONT}`; g.fillStyle = col; g.textAlign = align || 'left'; g.textBaseline = base || 'alphabetic'; g.fillText(t, x, y); g.restore(); }
      function topAxis(a) {
        if (!(a > 0)) return;
        g.save(); g.globalAlpha = a; g.strokeStyle = 'rgba(183, 192, 210, .3)'; g.lineWidth = 1;
        g.beginPath(); g.moveTo(PL, tBase + .5); g.lineTo(PL + PW, tBase + .5); g.stroke();
        g.font = `500 ${fs - 1}px ${MONO}`; g.fillStyle = SC.mut; g.textBaseline = 'top';
        [0, 5000, 10000].forEach((t, i) => { g.textAlign = i ? 'center' : 'left'; g.fillText(t ? num(t) : '0', Xt(t), tBase + 4); });
        g.textAlign = 'right'; g.fillText('чек, ₽', PL + PW, tBase + 4);
        g.restore();
      }
