        g.setLineDash([2, 4]); g.beginPath(); g.moveTo(Xb(0), bTop + fs + 4); g.lineTo(Xb(0), bBase); g.stroke(); g.setLineDash([]);
        g.font = `500 ${fs - 1}px ${MONO}`; g.fillStyle = SC.mut; g.textBaseline = 'top';
